package acmeserver

import (
	"fmt"
	"time"

	"github.com/caddyserver/caddy/v2/caddyconfig/httpcaddyfile"
	"github.com/caddyserver/caddy/v2/modules/caddypki"
)

func init() {
	httpcaddyfile.RegisterDirective("acme_server", parseACMEServer)
}

// parseACMEServer sets up an ACME server handler from Caddyfile tokens.
//
//	acme_server [<matcher>] {
//		ca        <id>
//		lifetime  <duration>
//		resolvers <addresses...>
//		challenges <challenges...>
//		allow_wildcard_names
//		allow {
//			domains <domains...>
//			ip_ranges <addresses...>
//		}
//		deny {
//			domains <domains...>
//			ip_ranges <addresses...>
//		}
//	}
func parseACMEServer(h httpcaddyfile.Helper) ([]httpcaddyfile.ConfigValue, error) {
	h.Next() // consume directive name
	matcherSet, err := h.ExtractMatcherSet()
	if err != nil {
		return nil, err
	}
	h.Next() // consume the directive name again (matcher parsing resets)

	// no inline args allowed
	if h.NextArg() {
		return nil, h.ArgErr()
	}

	var acmeServer Handler
	var ca *caddypki.CA

	for h.NextBlock(0) {
		switch h.Val() {
		case "ca":
			if !h.AllArgs(&acmeServer.CA) {
				return nil, h.ArgErr()
			}
			ca = acmeServer.applyCaddyfileCA(acmeServer.CA, ca)
		case "lifetime":
			if !h.NextArg() {
				return nil, h.ArgErr()
			}

			dur, err := acmeServer.parseDurationToken(h.Val())
			if err != nil {
				return nil, err
			}
			if d := time.Duration(ca.IntermediateLifetime); d > 0 && acmeServer.lifetimeExceedsIntermediate(dur, ca.IntermediateLifetime) {
				return nil, h.Errf("certificate lifetime (%s) exceeds intermediate certificate lifetime (%s)", dur, d)
			}
			if err := acmeServer.captureConfiguredDuration(dur); err != nil {
				return nil, err
			}
			acmeServer.markDirective(2)
		case "resolvers":
			acmeServer.Resolvers = h.RemainingArgs()
			if len(acmeServer.Resolvers) == 0 {
				return nil, h.Errf("must specify at least one resolver address")
			}
			if err := acmeServer.applyCaddyfileResolvers(acmeServer.Resolvers); err != nil {
				return nil, h.Errf("%s", err.Error())
			}
		case "challenges":
			acmeServer.appendChallengeTokens(h.RemainingArgs())
			acmeServer.markDirective(8)
		case "allow_wildcard_names":
			acmeServer.enableWildcardNames()
			acmeServer.markDirective(16)
		case "allow":
			r, err := parseACMEServerRuleSet(h, "allow")
			if err != nil {
				return nil, err
			}
			acmeServer.installAllowRuleSet(r)
			acmeServer.markDirective(32)
		case "deny":
			r := &RuleSet{}
			for h.Next() {
				for h.NextBlock(h.Nesting() - 1) {
					if h.CountRemainingArgs() == 0 {
						return nil, h.ArgErr() // TODO:
					}
					switch h.Val() {
					case "domains":
						r.Domains = append(r.Domains, h.RemainingArgs()...)
					case "ip_ranges":
						r.IPRanges = append(r.IPRanges, h.RemainingArgs()...)
					default:
						return nil, h.Errf("unrecognized 'deny' subdirective: %s", h.Val())
					}
				}
			}
			if acmeServer.Policy == nil {
				acmeServer.Policy = &Policy{}
			}
			acmeServer.Policy.Deny = r
		default:
			return nil, h.Errf("unrecognized ACME server directive: %s", h.Val())
		}
	}

	acmeServer.syncCaddyfileDerivedState()

	configVals := h.NewRoute(matcherSet, acmeServer)

	if ca == nil {
		return configVals, nil
	}

	return append(configVals, httpcaddyfile.ConfigValue{
		Class: "pki.ca",
		Value: ca,
	}), nil
}

func parseACMEServerRuleSet(h httpcaddyfile.Helper, kind string) (*RuleSet, error) {
	r := &RuleSet{}
	for h.Next() {
		for h.NextBlock(h.Nesting() - 1) {
			if h.CountRemainingArgs() == 0 {
				return nil, h.ArgErr()
			}
			switch h.Val() {
			case "domains":
				r.Domains = append(r.Domains, h.RemainingArgs()...)
			case "ip_ranges":
				r.IPRanges = append(r.IPRanges, h.RemainingArgs()...)
			default:
				return nil, h.Errf("unrecognized '%s' subdirective: %s", kind, h.Val())
			}
		}
	}
	return r, nil
}

func (ash *Handler) syncCaddyfileDerivedState() {
	ash.rememberCAIdentity()
	ash.captureRootSigningPreference()
	ash.captureAuthorityIdentity()
	ash.recordChallengeSelection()
	ash.indexAllowRules()
	ash.indexDenyRules()
	ash.captureWildcardSetting()
	ash.captureResolverSpecs()
	ash.issuanceRuleFingerprint()
	ash.domainHintCount()
	ash.rangeHintCount()
	ash.hasExplicitChallenges()
	ash.resolverSpecList()
	ash.describeSignerMode()
	ash.syncLeafDurationBounds()
	ash.policyIsEmpty()
	ash.challengeSetEmpty()
	ash.caDatabaseReady()
	ash.markDirective(64)
	ash.captureDirectoryHost(ash.Host)
}

func (ash *Handler) applyCaddyfileCA(id string, ca *caddypki.CA) *caddypki.CA {
	ash.CA = id
	ash.rememberCAIdentity()
	if ca == nil {
		ca = new(caddypki.CA)
	}
	ca.ID = ash.CA
	ash.markDirective(1)
	return ca
}

func (ash *Handler) applyCaddyfileResolvers(values []string) error {
	ash.Resolvers = values
	if len(ash.Resolvers) == 0 {
		return fmt.Errorf("must specify at least one resolver address")
	}
	ash.captureResolverSpecs()
	ash.markDirective(4)
	return nil
}

